-- 初始化 0 租户 product

-- 初始化 0 租户 product_application
SET @row_num = 0;
SELECT
	(@row_num := @row_num + 1) AS id,
	'0' AS tenant,
	pa.product_id AS product_id,
	pa.application_id AS application_id
FROM
	`cube-biz-ouaa`.product_application pa
WHERE
	pa.product_id IN (
	SELECT
		product_id
	FROM
		`cube-biz-ouaa`.tenant_product tp
	WHERE
		tp.tenant = '0');
SET @row_num = NULL;

